good_example.code:
// Clear specification
class Cache {
  private final Map data = Collections.synchronizedMap(new HashMap());

  /**
   * Thread-safe for concurrent reads and writes.
   * Multiple threads can read and write concurrently.
   */
  void put(K key, V value) { data.put(key, value); }
  V get(K key) { return data.get(key); }
}

// OR

class FastCache {
  private final Map data = new HashMap();  // NOT synchronized

  /**
   * Thread-safe for concurrent READS only.
   * For writes, caller must synchronize.
   * Safe pattern: Read frequently, write rarely under lock.
   */
  V get(K key) { return data.get(key); }
  synchronized void put(K key, V value) { data.put(key, value); }
}

bad_example.code:
// Wrong understanding
class Counter {
  int count = 0;

  void increment() {  // NO LOCK
    count++;  // Not atomic. Instruction interleaving corruption.
  }

  int getCount() {
    return count;  // Might see old cached value in other thread
  }
}

// Developer thought: 'Lock is about keeping threads out'
// Forgot: 'Lock is also about memory visibility'
// Result: Data corruption + visibility issues

good_example.code:
// Correct use of lock
class Counter {
  private int count = 0;
  private Object lock = new Object();

  void increment() {
    synchronized(lock) {  // Acquire lock
      count++;  // Only one thread here
              // Lock also ensures memory sync
    }  // Release lock. Changes visible to next acquirer.
  }

  int getCount() {
    synchronized(lock) {
      return count;  // Will see latest value
    }
  }
}

// Both guarantees: mutual exclusion + visibility

