good_example.code:
// Thread A
volatile boolean flag;  // volatile = acquire/release barriers

data = 42;
flag = true;  // Release barrier. Data write stays before this.

// Thread B
if (flag)  // Acquire barrier
  print(data);  // Definitely prints 42

// Volatile with acquire/release semantics guarantees ordering

