// Using monitor for complex state
class UserState {
  private Object lock = new Object();
  private int userCount;
  private String status;
  private List<Integer> items;

  synchronized void update(int count, String st, List<Integer> itms) {
    userCount = count;
    status = st;
    items = new ArrayList(itms);
  }
}

// Simple, clear, correct. All three updated atomically.

